; loop_ok.asm -- chapter 7: the count of three, testing BC itself
; generated by gen07.py
        INCLUDE "msx.inc"
        OUTPUT "loop_ok.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
        ld a, 1
        or a                    ; Z = 0: A is not 0
        ld bc, 3                ; three turns
count:  dec bc                  ; BC - 1
        ld a, b
        or c                    ; Z = 1 only when B and C are both 0
        jr nz, count            ; round again while BC is not 0
done:   jr done                 ; after three turns
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
